create_artifact_gardener_war_crown_effect = {
	# Get the character the artifact is being made for.
	$OWNER$ = { save_scope_as = owner }

	set_artifact_rarity_illustrious = yes

	# Create the artifact
	create_artifact = {	
		name = gardener_war_crown_name
		description = gardener_war_crown_description
		type = helmet
		visuals = gardener_war_crown_visuals
		wealth = scope:wealth
		quality = scope:quality
		template = gardener_war_crown_template
		history = {
			type = created
			date = 7692.1.8
			recipient = character:Gardener_75 # Meryn IV Gardener
			location = province:3237
		}
		modifier = gardener_war_crown_modifier
		save_scope_as = newly_created_artifact
		decaying = no
	}

	scope:newly_created_artifact = {
		set_variable = { name = crown_gardener_war_artifact value = yes }
		set_variable = { name = historical_unique_artifact value = yes }
		set_variable = {
			name = artifact_succession_title
			value = title:c_highgarden
		}
		add_artifact_title_history = {
			target = title:e_the_reach
			date = 7980.1.8
		}
	}

	hidden_effect = {
		dynasty:dynn_Gardener = {
			ordered_dynasty_member = {
				order_by = highest_held_title_tier
				house = { add_house_artifact_claim = scope:newly_created_artifact }
			}
		}
	}
}

